    print("Initial coin count: ", initial_count)
    if initial_count != 0:
        print("FAIL: Initial coin count is not 0")
        quit(1)
        return

    # 2. Test add_coin and signal
    var test_state = {
        "signal_received": false,
        "received_count": -1
    }
    inventory.coin_changed.connect(func(new_count: int):
        print("Signal handler lambda called with count: ", new_count)
        test_state["signal_received"] = true
        test_state["received_count"] = new_count
    )

    print("Calling inventory.add_coin()...")
    inventory.add_coin()
    print("After calling add_coin(). signal_received: ", test_state["signal_received"], ", received_count: ", test_state["received_count"])
    if test_state["received_count"] == 1 and test_state["signal_received"]:
        print("PASS: add_coin() incremented count and emitted signal.")
    else:
        print("FAIL: add_coin() did not work as expected. Received: ", test_state["received_count"])
        quit(1)
        return

    # 3. Test save
    inventory.save()
    if FileAccess.file_exists("user://save.json"):
        print("PASS: save() created user://save.json.")
        var file = FileAccess.open("user://save.json", FileAccess.READ)
        var content = file.get_as_text()
        file.close()
        print("Save file content: ", content)
        var data = JSON.parse_string(content)
        if data is Dictionary and data.get("count") == 1:
            print("PASS: save() wrote correct JSON data.")
        else:
            print("FAIL: save() wrote invalid JSON data.")
            quit(1)
            return
    else:
        print("FAIL: save() did not create save file.")
        quit(1)
        return

    # 4. Test load
